import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1788348152000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>This page is the prose version of the repository&#39;s <a href="https://github.com/ni-c/wg-easy-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>. For reporting a vulnerability, use <a href="https://github.com/ni-c/wg-easy-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a> — never a public issue.</p><h2 id="what-the-credentials-grant" tabindex="-1">What the credentials grant <a class="header-anchor" href="#what-the-credentials-grant" aria-label="Permalink to “What the credentials grant”">​</a></h2><p>The server authenticates with a wg-easy <strong>admin</strong> login. wg-easy has no read-only role, so there is no configuration in which this server holds less than full VPN administration. Concretely, anything able to read this process&#39;s environment can:</p><ul><li>create, disable and delete peers,</li><li>download any peer&#39;s configuration file and QR code, both of which contain that peer&#39;s <strong>private key</strong>,</li><li>mint one-time links that let an unauthenticated visitor download a config.</li></ul><p>Treat the process environment, the MCP client&#39;s config file and the tool output as three copies of the same secret.</p><h2 id="who-decides-what-gets-called" tabindex="-1">Who decides what gets called <a class="header-anchor" href="#who-decides-what-gets-called" aria-label="Permalink to “Who decides what gets called”">​</a></h2><p>The MCP client does. This server enforces the confirmation handshake and the redaction rules described below, but it cannot tell a legitimate request from one a model was talked into. Connect it only to clients you would trust with the VPN itself.</p><h2 id="guard-rails-in-the-server" tabindex="-1">Guard rails in the server <a class="header-anchor" href="#guard-rails-in-the-server" aria-label="Permalink to “Guard rails in the server”">​</a></h2><h3 id="five-tools-ask-a-person" tabindex="-1">Five tools ask a person <a class="header-anchor" href="#five-tools-ask-a-person" aria-label="Permalink to “Five tools ask a person”">​</a></h3><p><code>create_client</code>, <code>update_client</code>, <code>enable_client</code>, <code>delete_client</code> and <code>generate_one_time_link</code> put the question to a <strong>person</strong> before they act, through MCP elicitation — a dialog the model cannot answer on its behalf, and which nothing proceeds without.</p><p>Only one of the five destroys anything. The other four are on the list because <code>destructiveHint</code> is the wrong axis for what they do:</p><ul><li><code>create_client</code> issues a credential that reaches every network behind the VPN.</li><li><code>update_client</code> can move an address or widen <code>serverAllowedIps</code>. Its approval is bound to the <strong>exact edit</strong>, so approving a rename does not license a later call that widens the routes.</li><li><code>enable_client</code> re-arms a key pair that is already installed on a peer. If <code>disable_client</code> is the reversible revocation this server recommends — and its catalogue says it is — then enabling is the undo of a revocation. It was ungated until 0.5.0, which also made the guard on <code>update_client</code> avoidable: <code>update_client({enabled: true})</code> asked and <code>enable_client</code> did not, so the same state change was guarded or not depending on which tool the model picked.</li><li><code>generate_one_time_link</code> mints a URL that hands out a client&#39;s full configuration — private key included — to anyone who has it, without authentication.</li></ul><p><code>disable_client</code> deliberately stays ungated. It only ever withdraws access, and putting a dialog between an operator and cutting off a peer is the wrong place for one.</p><p>Where the client cannot show a dialog, all five fall back to a random 128-bit token bound to the same target and valid for <strong>five minutes</strong>; only a second call carrying that exact token acts. A boolean would not do: a model can set one by itself on the first call, including when it has been steered there by text it read somewhere.</p><p>Be clear about what the token proves, because this server is: <strong>the call was made twice with the same arguments, and nothing more.</strong> A model can read it out of the first result and quote it back in the same turn. The fallback text says so rather than implying somebody approved, and names whether it was the client that could not be asked or the operator who switched the dialog off with <code>ELICITATION=false</code>.</p><p>The prompt shows the client&#39;s <strong>name</strong> on a labelled line under a heading saying those values did not come from this server. A dialog that says only &quot;Delete client 5?&quot; is not something a person can act on; a name in the server&#39;s own sentence would read as the server vouching for it.</p><p>See <a href="/guide/approval">Asking a person</a>.</p><h3 id="key-material-is-redacted" tabindex="-1">Key material is redacted <a class="header-anchor" href="#key-material-is-redacted" aria-label="Permalink to “Key material is redacted”">​</a></h3><p>Everything the wg-easy API hands back is filtered before it is returned. Keys named <code>privateKey</code>, <code>preSharedKey</code>, <code>password</code>, <code>passwordHash</code>, <code>sessionSecret</code> or anything starting with <code>totp</code> are replaced with <code>[redacted]</code> at every nesting level.</p><p>That covers two different secrets. <code>get_server_info</code> reads the admin endpoints, which carry the WireGuard <strong>server</strong> private key. <code>get_client</code> reads a single client, and wg-easy returns that client&#39;s <strong>own</strong> private key and pre-shared key in full — while <code>list_clients</code> does not, which is what made the leak easy to miss. Until the integration suite found it, <code>get_client</code> passed the key straight through. A key that reaches the model is in the transcript, where it outlives any decision to stop using it.</p><p>The filter is applied to both, rather than to the one endpoint that happens to carry the key today.</p><p>One-time links are redacted on the read path too. <code>GET /api/client</code> carries the link token on every row, and <code>GET /cnf/&lt;token&gt;</code> returns the whole configuration with <strong>no login at all</strong> — so <code>list_clients</code> used to hand out a working download URL for any client whose link had not yet expired. The token is replaced; <code>expiresAt</code> is not, because knowing that a link is live is exactly what a listing is for.</p><p>Note the deliberate asymmetry: <code>get_client_config</code> and <code>get_client_qrcode</code> return private keys <strong>unredacted</strong>, and <code>generate_one_time_link</code> returns the link token, because handing a peer its configuration is the point of those tools. Their descriptions say so. The difference is that somebody asked for it.</p><h3 id="read-only-mode-suppresses-key-disclosure" tabindex="-1">Read-only mode suppresses key disclosure <a class="header-anchor" href="#read-only-mode-suppresses-key-disclosure" aria-label="Permalink to “Read-only mode suppresses key disclosure”">​</a></h3><p><code>WG_EASY_READ_ONLY=true</code> registers <code>list_clients</code>, <code>get_client</code> and <code>get_server_info</code>, and nothing else.</p><p><code>get_client_config</code> and <code>get_client_qrcode</code> are reads — nothing on the instance changes — and they are <strong>not</strong> in that set, because what they read is a client&#39;s <code>PrivateKey</code> in the clear. Read-only mode is the one coarse switch an operator has for putting this server in front of a less trusted session, and a mode that leaves key disclosure standing is not the mode its name promises: <code>list_clients</code> followed by <code>get_client_config</code> yields one ready-to-use VPN configuration per peer, in the transcript, with no confirmation anywhere.</p><p>They are left out of <code>WG_EASY_ALLOW_TOOLS=essential</code> for the same reason. Where a session should also hand out configurations, name the tool:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>WG_EASY_ALLOW_TOOLS=essential,get_client_config</span></span></code></pre></div><p>This is the rule the catalogue already applies to <code>delete_client</code> — the variant that cannot be taken back has to be named explicitly — applied to disclosure rather than to destruction. Before 0.5.0 both tools counted as read tools, so <code>WG_EASY_READ_ONLY</code> changed nothing about them.</p><h3 id="the-two-call-token-proves-binding-not-freshness" tabindex="-1">The two-call token proves binding, not freshness <a class="header-anchor" href="#the-two-call-token-proves-binding-not-freshness" aria-label="Permalink to “The two-call token proves binding, not freshness”">​</a></h3><p>Where a client cannot show a dialog, a guarded tool hands back a <code>confirm_token</code> and acts only on a second call carrying it. Where a client <em>can</em>, the reply comes back sealed (HMAC) and carries the resource key of the operation it answered.</p><p>Both mechanisms bind an answer to <strong>one operation with one set of arguments</strong>. Neither proves that the answer is <em>recent</em>. A sealed <code>requestState</code> that opens onto the same operation opens onto it whenever it is replayed, and the library says so.</p><p>In this server that gap is closed by the surroundings rather than by a mechanism, and it is worth writing down which surroundings, because they are what a future change could remove:</p><ul><li>The sealing key is 32 random bytes <strong>per process</strong>. This is a stdio server spawned per session, so a state sealed in one session cannot be opened in the next.</li><li><code>requestState</code> only travels over the wire on protocol revision <code>2026-07-28</code>. On <code>2025-11-25</code> the SDK bridges the elicitation server-side and the value never leaves the process. This server offers neither revision explicitly: it does not set <code>supportedProtocolVersions</code>, so it takes the SDK&#39;s default list, which ends at <code>2025-11-25</code>.</li><li>The <code>confirm_token</code> path is single-use by construction — <code>ConfirmationStore</code> consumes the token — and expires after five minutes.</li></ul><p>So there is nothing here to replay, and <strong>no replay defence has been built</strong>. If this server ever negotiates <code>2026-07-28</code>, or serves two halves of one flow from two processes with a shared key, this section stops being true and a nonce is needed. That applies first to <code>create_client</code> and <code>generate_one_time_link</code>, whose approvals are the ones worth stealing.</p><h3 id="upstream-content-is-marked-untrusted" tabindex="-1">Upstream content is marked untrusted <a class="header-anchor" href="#upstream-content-is-marked-untrusted" aria-label="Permalink to “Upstream content is marked untrusted”">​</a></h3><p>Client names, DNS entries and endpoints are free-form strings chosen by whoever administers the VPN. Everything the wg-easy API returns is prefixed with an explicit untrusted-data marker telling the model to treat the block as data to report rather than instructions to follow, and is capped at 60 000 characters so a single oversized field cannot flood the context.</p><h3 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to “Transport”">​</a></h3><ul><li>Requests carry a <strong>15-second timeout</strong> and <code>redirect: &#39;error&#39;</code> — following a redirect would hand the <code>Authorization</code> header to whatever host it points at.</li><li><code>WG_EASY_INSECURE_TLS</code> is a <strong>scoped undici dispatcher</strong>, so relaxed certificate validation applies to the wg-easy connection only and never process-wide.</li><li>A URL carrying embedded credentials is rejected at startup rather than logged.</li><li>Credentials are removed from <code>process.env</code> after the config is read.</li></ul><h3 id="error-output" tabindex="-1">Error output <a class="header-anchor" href="#error-output" aria-label="Permalink to “Error output”">​</a></h3><p>Upstream error bodies are truncated to 2 000 characters, and HTML error pages — the usual output of a reverse proxy or WAF — are dropped entirely instead of being pasted into the model&#39;s context.</p><h2 id="deployment-recommendations" tabindex="-1">Deployment recommendations <a class="header-anchor" href="#deployment-recommendations" aria-label="Permalink to “Deployment recommendations”">​</a></h2><ul><li>Keep the wg-easy admin UI reachable only from trusted networks. The MCP server uses the same URL and inherits exactly that exposure.</li><li>Give the server its own admin account where wg-easy supports multiple users, and rotate its password when you revoke access.</li><li>Pass credentials through the client&#39;s <code>env</code> block — not a command line, where they land in shell history and <code>ps</code>.</li><li>Prefer an internal CA over <code>WG_EASY_INSECURE_TLS</code>.</li></ul><h2 id="supply-chain" tabindex="-1">Supply chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to “Supply chain”">​</a></h2><p>Releases are published to npm via <a href="https://docs.npmjs.com/trusted-publishers" target="_blank" rel="noreferrer">Trusted Publishing</a> with <a href="https://docs.npmjs.com/generating-provenance-statements" target="_blank" rel="noreferrer">provenance</a> — no long-lived token exists to leak. Container images ship an SBOM and <code>provenance: mode=max</code>. CI runs <code>npm audit</code>, CodeQL and a Trivy scan of the image on every push and once a week; the runtime image contains no npm at all.</p>`,46)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};